CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INTEGER CHECK(c0 IS NULL OR length(c0) < 40), c1 REAL DEFAULT 'd', c2 INTEGER NOT NULL DEFAULT 0, c3 VARCHAR(10), c4 BLOB);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(NULL, 995, 'café', NULL, 'iota');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(x'919a', 'nu', x'', -403, -445);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0, c1 INTEGER NOT NULL DEFAULT 0, c2 INT COLLATE NOCASE, c3 TEXT COLLATE NOCASE, c4 NUMERIC, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(NULL, 'kappa', 9223372036854775807, 'xi', x'b8526b', 6);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(-7, 632.4861, NULL, 'über', NULL, 1);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(NULL, 4.5e-310, 2, x'd846', -536, 8);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(x'c27ffa15b0', '-7', 0, 2, 1e-7, 3);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(0.1, -246, -0.0, -666, 684, 7);
SELECT length('gamma'), upper('gamma'), lower('gamma'), substr('gamma', -2, 4), instr('gamma', 'café'), replace('gamma', 'é', ''), trim('gamma'), ltrim('gamma', 'ab'), hex('gamma'), quote('gamma'), unicode('gamma'), 'gamma' LIKE '%é%', 'gamma' GLOB 'a*', char(80, 988), 'gamma' || 'café', 'gamma' < 'café', 'gamma' = 'café' COLLATE NOCASE;
SELECT length('iota'), upper('iota'), lower('iota'), substr('iota', -2, 0), instr('iota', ''), replace('iota', '', 'XY'), trim('iota'), ltrim('iota', 'ab'), hex('iota'), quote('iota'), unicode('iota'), 'iota' LIKE 'a%', 'iota' GLOB '*[a-m]*', char(79, 553), 'iota' || '', 'iota' < '', 'iota' = '' COLLATE NOCASE;
SELECT length('Ελλάδα'), upper('Ελλάδα'), lower('Ελλάδα'), substr('Ελλάδα', 4, 3), instr('Ελλάδα', '1e3'), replace('Ελλάδα', 'é', 'XY'), trim('Ελλάδα'), ltrim('Ελλάδα', 'ab'), hex('Ελλάδα'), quote('Ελλάδα'), unicode('Ελλάδα'), 'Ελλάδα' LIKE '%', 'Ελλάδα' GLOB '*', char(70, 972), 'Ελλάδα' || '1e3', 'Ελλάδα' < '1e3', 'Ελλάδα' = '1e3' COLLATE NOCASE;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', -2, 1), instr('pi', 'zeta'), replace('pi', 'a', ''), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE 'A%', 'pi' GLOB 'a*', char(87, 931), 'pi' || 'zeta', 'pi' < 'zeta', 'pi' = 'zeta' COLLATE NOCASE;
SELECT length('alpha'), upper('alpha'), lower('alpha'), substr('alpha', 0, 0), instr('alpha', 'eta'), replace('alpha', '', '_'), trim('alpha'), ltrim('alpha', 'ab'), hex('alpha'), quote('alpha'), unicode('alpha'), 'alpha' LIKE '%é%', 'alpha' GLOB 'a*', char(81, 545), 'alpha' || 'eta', 'alpha' < 'eta', 'alpha' = 'eta' COLLATE NOCASE;
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', 4, 3), instr('nu', '日本'), replace('nu', 'e', ''), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE 'A%', 'nu' GLOB '*[a-m]*', char(66, 761), 'nu' || '日本', 'nu' < '日本', 'nu' = '日本' COLLATE NOCASE;
SELECT length('kappa'), upper('kappa'), lower('kappa'), substr('kappa', -1, 5), instr('kappa', 'a%b'), replace('kappa', '', 'XY'), trim('kappa'), ltrim('kappa', 'ab'), hex('kappa'), quote('kappa'), unicode('kappa'), 'kappa' LIKE '%é%', 'kappa' GLOB '*', char(70, 600), 'kappa' || 'a%b', 'kappa' < 'a%b', 'kappa' = 'a%b' COLLATE NOCASE;
SELECT id, -(id), 2.5 BETWEEN 0 AND CAST(NOT 0 AS BLOB) FROM t1 ORDER BY id DESC, c0, c1, c2 DESC, c3, c4, ref DESC;
